{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "In humans, [11C]AZ10419369, a close analogue containing an N-methylpiperazine and amide linker, was rapidly distributed into brain with 3–4% of injected radioactivity at peak, demonstrating meaningful CNS access despite rodent efflux liability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "In cynomolgus monkeys, radioligands with N-methylpiperazine and morpholine anilide amide motifs reached 5–6% ID peak brain radioactivity, showing good BBB penetration for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A tetrahydropyran-containing amide analogue achieved a brain:plasma ratio of 1.29 in mice, indicating good CNS penetration for a structurally related scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A morpholine/amide heteroaromatic analogue showed Kp of 11.4 with negligible P-gp efflux in mice, supporting strong CNS access for similar polar amide/heteroaryl compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A more complex piperazine amide PET ligand had very low peak brain radioactivity (0.7% ID) attributed to P-gp efflux, providing a counterexample in the broader chemical space.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: multiple direct primate/human and rodent brain-uptake measurements for analogues sharing the N-methylpiperazine, amide, and aryl/heteroaryl features show meaningful CNS access; the single low-uptake analogue differs by an N-acyl piperazine and higher polarity, and is outweighed by convergent supportive evidence.",
  "evidence_gaps": [
    "No direct experimental CNS measurement for the query molecule itself.",
    "Potential P-gp/ABC transporter efflux for the query is not directly assessed; rodent efflux seen for some analogues may not preclude human CNS access.",
    "Unbound brain/plasma concentrations and CSF data are not available for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

